import{_ as i,c as n,o as t,ag as a}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"SUAS Operating Conditions","description":"","frontmatter":{"title":"SUAS Operating Conditions"},"headers":[],"relativePath":"general/suas-operating-conditions.md","filePath":"general/suas-operating-conditions.md","lastUpdated":null}'),o={name:"general/suas-operating-conditions.md"};function r(s,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="suas-operating-conditions" tabindex="-1">SUAS Operating Conditions <a class="header-anchor" href="#suas-operating-conditions" aria-label="Permalink to &quot;SUAS Operating Conditions&quot;">​</a></h1><h2 id="operating-conditions-for-suas" tabindex="-1">Operating Conditions for sUAS <a class="header-anchor" href="#operating-conditions-for-suas" aria-label="Permalink to &quot;Operating Conditions for sUAS&quot;">​</a></h2><h3 id="arctic-uas-operations-discussion" tabindex="-1">Arctic UAS Operations Discussion <a class="header-anchor" href="#arctic-uas-operations-discussion" aria-label="Permalink to &quot;Arctic UAS Operations Discussion&quot;">​</a></h3><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>This section focuses on the unique challenges and potential solutions for operating small unmanned aerial systems (sUAS) in Arctic environments. Key contributors, including Roger O’ and others, share their experiences and insights into operating in these extreme conditions.</p><p>For operations conducted in conditions such as hot/cold weather, turbulence, rain/thunderstorm, desert/sand/dust, or wind, reference system limitations in the operator’s manual, , and</p><h3 id="key-discussion-points" tabindex="-1">Key Discussion Points <a class="header-anchor" href="#key-discussion-points" aria-label="Permalink to &quot;Key Discussion Points&quot;">​</a></h3><h4 id="challenges-in-arctic-uas-operations" tabindex="-1">Challenges in Arctic UAS Operations <a class="header-anchor" href="#challenges-in-arctic-uas-operations" aria-label="Permalink to &quot;Challenges in Arctic UAS Operations&quot;">​</a></h4><p><strong>Darkness:</strong> Impacts optical capabilities during winter.</p><ul><li>Darkness (it’s dark in the winter, so optics fail).</li></ul><p><strong>GPS/Satcom Degradation:</strong> Navigational challenges due to signal degradation.</p><p><strong>Lack of Overhead Imagery/Terrain Models:</strong> Limits operational awareness.</p><p><strong>Material Brittleness in Cold:</strong> Affects the durability of drone components.</p><p><strong>User Experience Challenges:</strong> Due to extreme cold conditions.</p><h4 id="technical-considerations" tabindex="-1">Technical Considerations <a class="header-anchor" href="#technical-considerations" aria-label="Permalink to &quot;Technical Considerations&quot;">​</a></h4><ul><li><p><strong>RF Environment:</strong> Limited RF in the Arctic, affecting signal propagation.</p></li><li><p>Otherwise, there is not much RF in the region, and usually, the terrain is pretty flat, so you get good propagation.</p></li><li><p><strong>Optics and Sensors:</strong> Performance of EO/IR sensors against different snow types.</p></li><li><p>Factors at play with Arctic that aren’t immediately obvious include the RF environment, EO/IR performance against different types of snow, battery/power considerations, etc.</p></li><li><p><strong>Battery/Power:</strong> Impact of cold on battery efficiency and power management.</p></li></ul><h4 id="material-and-component-considerations" tabindex="-1">Material and Component Considerations <a class="header-anchor" href="#material-and-component-considerations" aria-label="Permalink to &quot;Material and Component Considerations&quot;">​</a></h4><ul><li><p><strong>Blade Performance and Material Durability:</strong></p></li><li><p>Carbon fiber (CF) can chip and delaminate under stress. The longevity of the drone is a concern with prolonged use in harsh conditions.</p></li><li><p><strong>3D Printed Components:</strong></p></li><li><p>It is advised to avoid 3D printed propellers unless no other options are available due to their reduced durability and reliability in cold conditions.</p></li><li><p><strong>Material Adaptations for Arctic Conditions:</strong></p></li><li><p>Use of <a href="https://mocap.com/silicone-tape.html" target="_blank" rel="noreferrer">mocap tape</a> on leading edges, degreasing servos, and saline thermal masses.</p></li><li><p>Thermoplastics and aluminum extrusions from suppliers like McMaster are noted for their survivability.</p></li><li><p>Challenges with CF and fiberglass in recovery operations, especially when payload mounting affects structural integrity.</p></li><li><p><strong>Long Endurance Flights:</strong></p></li><li><p>For flight times exceeding 3 months, power components and connections may fail before the airframe, around 100 days of continuous flight.</p></li></ul><h4 id="battery-and-power-management" tabindex="-1">Battery and Power Management <a class="header-anchor" href="#battery-and-power-management" aria-label="Permalink to &quot;Battery and Power Management&quot;">​</a></h4><ul><li><p><strong>Voltage Sag in Cold Conditions:</strong></p></li><li><p>Batteries experience voltage sag when exposed to cold air, even if initially warm.</p></li><li><p><strong>Battery Storage and Usage in Cold:</strong></p></li><li><p>Effective at -10°C if stored and charged in a warm place and protected from airflow.</p></li><li><p>If batteries are internal to an airframe, there is only marginal degradation in performance.</p></li></ul><h4 id="drone-operating-limitations-in-cold" tabindex="-1">Drone Operating Limitations in Cold <a class="header-anchor" href="#drone-operating-limitations-in-cold" aria-label="Permalink to &quot;Drone Operating Limitations in Cold&quot;">​</a></h4><ul><li><p><strong>Operational Temperature Limits:</strong></p></li><li><p>Successful operation of drones is challenging below -20°C, with limited success noted below -12°C.</p></li></ul><h4 id="testing-and-simulation-for-arctic-conditions" tabindex="-1">Testing and Simulation for Arctic Conditions <a class="header-anchor" href="#testing-and-simulation-for-arctic-conditions" aria-label="Permalink to &quot;Testing and Simulation for Arctic Conditions&quot;">​</a></h4><ul><li><p><strong>Low-Cost Testing Methods:</strong></p></li><li><p>Using a Yeti cooler with dry ice to simulate cold conditions for vacuum testing.</p></li><li><p>Mock-up wind tunnel with mist and fog in a freezer or outdoor cold environment for real-world testing.</p></li><li><p><strong>Software and Stress Testing:</strong></p></li><li><p>Utilizing SolidWorks for thermal modeling and load simulations.</p></li><li><p>Using balloons for stress testing materials and electronics under part 101 regulations.</p></li></ul><h3 id="further-research-and-development" tabindex="-1">Further Research and Development <a class="header-anchor" href="#further-research-and-development" aria-label="Permalink to &quot;Further Research and Development&quot;">​</a></h3><ul><li><p><strong>Advanced Coatings:</strong> Research into graphene and other icephobic coatings.</p></li><li><p><strong>Custom Motor Design:</strong> For effective heated propellers.</p></li><li><p><strong>Minimizing Icing Impact:</strong> Exploring de-icing fluids and long-lasting coatings.</p></li><li><p><strong>Innovative Heating Solutions:</strong> Nichrome wires, resistive elements, and thermal management systems.</p></li></ul><h3 id="additional-considerations-from-recent-discussions" tabindex="-1">Additional Considerations from Recent Discussions <a class="header-anchor" href="#additional-considerations-from-recent-discussions" aria-label="Permalink to &quot;Additional Considerations from Recent Discussions&quot;">​</a></h3><ul><li><p><strong>Sound Propagation and Stealth:</strong> Ice affects stealth coatings or designs, leading to potential detection.</p></li><li><p><strong>Pilot Dexterity and Comfort:</strong> Importance of maintaining finger dexterity and strategies for operating in cold environments.</p></li><li><p><strong>Terrain Awareness and Threat Detection:</strong> Utilizing high vantage points and thermal optics for long-range visibility and threat assessment.</p></li><li><p><strong>Visibility and Movement:</strong> Thermal blankets are ineffective in masking the heat signature of a moving person.</p></li><li><p><strong>Maintenance and Field Adaptations:</strong> Recommendations for equipment and strategies to maintain operational efficiency in cold climates.</p></li></ul><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>[Required] [Systems] [Learned] [Operations]</p>',30)])])}const u=i(o,[["render",r]]);export{h as __pageData,u as default};
